/* ==========================================================================
   tahlil.js — طبقة التحليل
   ------------------------------------------------------------------
   قاعدة هذا الملف: كلُّ ما وُضِع في حقلٍ اسمه «nass» أو «matn» فهو
   منقولٌ بحروفه من كلام ابن رشد في المصدر، ويتحقق من ذلك آليًا
   بـ `node tools/verify.mjs`، فإن خالف حرفٌ حرفًا سقط البناء.
   وكلُّ ما وُضِع في حقلٍ اسمه «sharh» فهو من كلام المحرِّر، ويُعرض
   في الموقع موسومًا بـ«شرح المحرِّر» بلونٍ وخطٍّ مغايرين.
   ========================================================================== */

